-- Complete the Education & Tuition filter master data so GET /api/tuition/filters returns a real
-- subjects/levels list instead of empty arrays, across the whole tuition vertical (education-tuition
-- and all of its direct children), not just School Tuition.
--
-- Root cause of the empty subjects/levels (see TuitionFilterMetadataService): `subject` and
-- `grade` were seeded as dataType TEXT (free text), so attribute_options - the table the filter
-- endpoint reads - never had any rows for them. Master-data/configuration only: no schema changes,
-- no new tables/columns, no edits to already-applied migrations (V1-V9). ad_attribute_values.value_text
-- is a plain varchar shared by TEXT and SELECT alike, so flipping data_type to SELECT does not
-- touch or corrupt any stored ad value.
--
-- Existing free-text ad_attribute_values are preserved as-is; none are rewritten by this migration.
-- Two free-text values used by seeded ads ("Combined Mathematics", "Spoken English") would not have
-- matched the new canonical SELECT values case-insensitively (matchOption() in AdAttributeService
-- does not normalize whitespace/punctuation), so LocalDataSeeder's own seed data (not production ad
-- data) was updated separately to use the canonical values (COMBINED_MATHEMATICS, SPOKEN_ENGLISH,
-- OL, AL, PRIMARY) - see LocalDataSeeder#tuitionAdSeeds. No real ad content is touched by this file.
--
-- curriculum/classMode stable *values* are intentionally left untouched (LOCAL, EDEXCEL, CAMBRIDGE,
-- IB, PROFESSIONAL, PHYSICAL, ONLINE, BOTH) to preserve any existing ad_attribute_values - only
-- labels/display_order/required are corrected, and BOTH keeps its existing "Online & Physical"
-- label (Option A from the task) rather than being renamed, so no ad using BOTH is affected.
--
-- Per-category (not root-level) subject/grade/classMode definitions are intentional, not
-- unnecessary duplication: AdAttributeService.buildValues resolves attribute definitions strictly
-- by the ad's own leaf category id with no ancestor-chain inheritance (unlike the generic
-- /api/categories/{slug}/filters endpoint, which does inherit from ancestors for search-filter
-- display only). A single root-level definition on education-tuition would be invisible to Post Ad
-- validation for every leaf category, so per-category definitions are what "the existing
-- architecture absolutely requires" here. Changing AdAttributeService to support inherited
-- definitions would affect posting for every category in the marketplace, not just tuition, which
-- is out of scope for this master-data-only task.

-- ============================================================================
-- 1. Convert subject/grade from TEXT to SELECT so they can carry attribute_options.
--    value_text storage is identical between TEXT and SELECT, so this is a metadata-only change.
-- ============================================================================
UPDATE attribute_definitions SET data_type = 'SELECT'
WHERE data_type = 'TEXT' AND attribute_key = 'subject'
  AND category_id IN (SELECT id FROM categories WHERE slug IN
      ('school-tuition', 'music', 'dancing', 'drama-theatre', 'art-creative-classes', 'technology-coding'));

UPDATE attribute_definitions SET data_type = 'SELECT'
WHERE data_type = 'TEXT' AND attribute_key = 'grade'
  AND category_id IN (SELECT id FROM categories WHERE slug = 'school-tuition');

-- ============================================================================
-- 2. Curriculum corrections on School Tuition (only place curriculum exists): required -> false,
--    label/display_order corrections. Stable values (LOCAL, EDEXCEL, CAMBRIDGE, IB, PROFESSIONAL)
--    are preserved so existing ad_attribute_values keep resolving.
-- ============================================================================
UPDATE attribute_definitions SET required = false
WHERE attribute_key = 'curriculum' AND required = true
  AND category_id IN (SELECT id FROM categories WHERE slug = 'school-tuition');

UPDATE attribute_options SET label = 'Sri Lankan National', display_order = 10
WHERE option_value = 'LOCAL' AND attribute_definition_id IN (
    SELECT d.id FROM attribute_definitions d JOIN categories c ON c.id = d.category_id
    WHERE c.slug = 'school-tuition' AND d.attribute_key = 'curriculum');
UPDATE attribute_options SET display_order = 20
WHERE option_value = 'CAMBRIDGE' AND attribute_definition_id IN (
    SELECT d.id FROM attribute_definitions d JOIN categories c ON c.id = d.category_id
    WHERE c.slug = 'school-tuition' AND d.attribute_key = 'curriculum');
UPDATE attribute_options SET label = 'Pearson Edexcel', display_order = 30
WHERE option_value = 'EDEXCEL' AND attribute_definition_id IN (
    SELECT d.id FROM attribute_definitions d JOIN categories c ON c.id = d.category_id
    WHERE c.slug = 'school-tuition' AND d.attribute_key = 'curriculum');
UPDATE attribute_options SET display_order = 40
WHERE option_value = 'IB' AND attribute_definition_id IN (
    SELECT d.id FROM attribute_definitions d JOIN categories c ON c.id = d.category_id
    WHERE c.slug = 'school-tuition' AND d.attribute_key = 'curriculum');
UPDATE attribute_options SET display_order = 50
WHERE option_value = 'PROFESSIONAL' AND attribute_definition_id IN (
    SELECT d.id FROM attribute_definitions d JOIN categories c ON c.id = d.category_id
    WHERE c.slug = 'school-tuition' AND d.attribute_key = 'curriculum');

-- Medium (SINHALA/ENGLISH/TAMIL) already correct - no changes.

-- ============================================================================
-- 3. New attribute definitions for the categories that don't yet have subject/grade/classMode.
-- ============================================================================




-- Technology & Coding gets a grade/level definition too (see task example: Programming level can
-- be PROFESSIONAL or unset) - classMode's display_order shifts from 20 to 30 to make room.
UPDATE attribute_definitions SET display_order = 30
WHERE attribute_key = 'classMode' AND display_order = 20
  AND category_id IN (SELECT id FROM categories WHERE slug = 'technology-coding');

